156	                    cpf VARCHAR(11) PRIMARY KEY,
157	                    credit_balance DECIMAL(10, 2) NOT NULL DEFAULT 0
158	                )
159	            """);
160	
161	            stmt.execute("""
162	                CREATE TABLE IF NOT EXISTS orders (
163	                    id VARCHAR(50) PRIMARY KEY,
164	                    customer_cpf VARCHAR(11) NOT NULL,
165	                    customer_email VARCHAR(255) NOT NULL,
166	                    status VARCHAR(50) NOT NULL,
167	                    created_at TIMESTAMP NOT NULL,
168	                    tracking_code VARCHAR(255),
