173	                    shipping_cost DECIMAL(10, 2) NOT NULL,
174	                    delivery_days INTEGER NOT NULL,
175	                    insurance DECIMAL(10, 2) NOT NULL,
176	                    payment_adjustment DECIMAL(10, 2) NOT NULL,
