218	package com.loja.infrastructure;
219	
220	import com.google.gson.Gson;
221	import com.google.gson.JsonObject;
222	
223	import java.io.IOException;
224	import java.net.URI;
225	import java.net.http.HttpClient;
226	import java.net.http.HttpRequest;
227	import java.net.http.HttpResponse;
228	import java.time.Duration;
229	
230	public class TransLogClient {
231	    private final String baseUrl;
232	    private final HttpClient httpClient;
233	    private final Gson gson;
234	
235	    public TransLogClient(String baseUrl) {
236	        this.baseUrl = baseUrl;
237	        this.httpClient = HttpClient.newBuilder()
238	                .connectTimeout(Duration.ofSeconds(2))
239	                .build();
240	        this.gson = new Gson();
241	    }
242	
243	    public TransLogQuote getQuote(String zipCode, double weightKg, TransLogService service) throws TransLogException {
244	        int weightG = (int) (weightKg * 1000);
245	        String serviceCode = service == TransLogService.ECONOMY ? "STD" : "EXP";
246	
247	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
248	                baseUrl, zipCode, weightG, serviceCode);
249	
250	        HttpRequest request = HttpRequest.newBuilder()
251	                .uri(URI.create(url))
252	                .timeout(Duration.ofSeconds(2))
253	                .GET()
254	                .build();
255	
256	        try {
257	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
258	
259	            if (response.statusCode() != 200) {
260	                throw new TransLogException("TransLog returned status " + response.statusCode());
261	            }
262	
263	            JsonObject json = gson.fromJson(response.body(), JsonObject.class);
264	
265	            if (json.has("error")) {
266	                String error = json.get("error").getAsString();
267	                if ("ZIP_NOT_SERVED".equals(error)) {
268	                    throw new ZipNotServedException("ZIP not served by TransLog");
269	                }
270	                throw new TransLogException("TransLog error: " + error);
271	            }
272	
273	            int priceCents = json.get("price_cents").getAsInt();
274	            int etaHours = json.get("eta_hours").getAsInt();
275	
276	            return new TransLogQuote(priceCents, etaHours);
277	
278	        } catch (IOException | InterruptedException e) {
279	            throw new TransLogException("Failed to connect to TransLog", e);
280	        }
281	    }
282	
283	    public enum TransLogService {
284	        ECONOMY,
285	        EXPRESS
286	    }
287	
288	    public static class TransLogQuote {
289	        private final int priceCents;
290	        private final int etaHours;
291	
292	        public TransLogQuote(int priceCents, int etaHours) {
293	            this.priceCents = priceCents;
294	            this.etaHours = etaHours;
295	        }
296	
297	        public double getPriceReais() {
298	            return priceCents / 100.0;
299	        }
300	
301	        public int getDeliveryDays() {
302	            return (int) Math.ceil(etaHours / 24.0);
303	        }
304	    }
305	
306	    public static class TransLogException extends Exception {
307	        public TransLogException(String message) {
308	            super(message);
309	        }
310	
311	        public TransLogException(String message, Throwable cause) {
312	            super(message, cause);
313	        }
314	    }
315	
316	    public static class ZipNotServedException extends TransLogException {
317	        public ZipNotServedException(String message) {
318	            super(message);
319	        }
320	    }
321	}

