import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class Stub {
    static volatile String mode = "ok";
    static volatile String body = "{\"price_cents\":3310,\"eta_hours\":41}";
    static volatile long delayMs = 0;
    static volatile String onlyZip = null; // if set, other zips get ZIP_NOT_SERVED
    static final List<String> log = Collections.synchronizedList(new ArrayList<>());

    static Map<String,String> q(URI u) {
        Map<String,String> m = new HashMap<>();
        String s = u.getRawQuery(); if (s == null) return m;
        for (String p : s.split("&")) { String[] kv = p.split("=",2); m.put(kv[0], kv.length>1?URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8):""); }
        return m;
    }
    static void send(HttpExchange ex, int code, String b) throws IOException {
        byte[] bs = b.getBytes();
        ex.getResponseHeaders().add("Content-Type","application/json");
        ex.sendResponseHeaders(code, bs.length);
        ex.getResponseBody().write(bs); ex.close();
    }
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(9090), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/__set", ex -> {
            Map<String,String> m = q(ex.getRequestURI());
            if (m.containsKey("mode")) mode = m.get("mode");
            if (m.containsKey("body")) body = m.get("body");
            if (m.containsKey("delay")) delayMs = Long.parseLong(m.get("delay"));
            if (m.containsKey("onlyZip")) onlyZip = m.get("onlyZip").isEmpty()?null:m.get("onlyZip");
            log.clear();
            send(ex, 200, "{\"mode\":\""+mode+"\"}");
        });
        s.createContext("/__log", ex -> { String r; synchronized(log){ r = String.join("\n", log);} send(ex, 200, r + "\n"); });
        s.createContext("/v2/quote", ex -> {
            log.add(ex.getRequestURI().toString());
            try { if (delayMs > 0) Thread.sleep(delayMs); } catch (InterruptedException e) {}
            Map<String,String> m = q(ex.getRequestURI());
            if (onlyZip != null && !onlyZip.equals(m.get("zip"))) { send(ex, 200, "{\"error\":\"ZIP_NOT_SERVED\"}"); return; }
            switch (mode) {
                case "ok" -> send(ex, 200, body);
                case "zip" -> send(ex, 200, "{\"error\":\"ZIP_NOT_SERVED\"}");
                case "500" -> send(ex, 500, "{\"oops\":true}");
                case "garbage" -> send(ex, 200, "<html>maintenance</html>");
                case "othererr" -> send(ex, 200, "{\"error\":\"RATE_LIMIT\"}");
                default -> send(ex, 200, body);
            }
        });
        s.start();
        System.out.println("stub on 9090");
    }
}
